import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

exclusive_scan_source = """
#include <torch/extension.h>

__global__ void exclusive_scan_kernel(const float* input, float* output, int L, int S) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= S) return;

    const float* row_input = input + row * L;
    float* row_output = output + row * L;

    row_output[0] = 0.0f;
    float sum = 0.0f;
    for (int i = 1; i < L; ++i) {
        sum += row_input[i-1];
        row_output[i] = sum;
    }
}

torch::Tensor exclusive_scan_cuda(torch::Tensor input, int L, int S) {
    auto output = torch::zeros_like(input);
    const int threads_per_block = 128;
    const int num_blocks = (S + threads_per_block - 1) / threads_per_block;
    exclusive_scan_kernel<<<num_blocks, threads_per_block>>>(
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        L, 
        S
    );
    return output;
}
"""

exclusive_scan_cpp_source = "torch::Tensor exclusive_scan_cuda(torch::Tensor input, int L, int S);"

exclusive_scan = load_inline(
    name="exclusive_scan",
    cpp_sources=exclusive_scan_cpp_source,
    cuda_sources=exclusive_scan_source,
    functions=["exclusive_scan_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.exclusive_scan = exclusive_scan

    def forward(self, x):
        original_shape = x.shape
        dim_size = x.size(self.dim)

        # Permute and flatten for kernel
        x_permuted = x.transpose(self.dim, -1).contiguous()
        x_flattened = x_permuted.view(-1, dim_size)

        # Get dimensions
        S = x_flattened.size(0)
        L = x_flattened.size(1)

        # Apply optimized exclusive scan
        output_flattened = self.exclusive_scan.exclusive_scan_cuda(x_flattened, L, S)

        # Reshape back to original dimensions
        output_permuted = output_flattened.view(x_permuted.shape)
        return output_permuted.transpose(self.dim, -1).contiguous()
